import pickle, numpy as np, pysam, itertools, collections
W='/task/work'
samples=[l.strip() for l in open(W+'/samples.txt')]
tp=np.load(W+'/tpos.npy')
candk=pickle.load(open(W+'/cand.pkl','rb'))['cand']
cand=[int(tp[k]) for k in candk]
candpos={p:i for i,p in enumerate(sorted(set(cand)))}
fa=pysam.FastaFile(W+'/ref.fa'); refseq=fa.fetch('chr22_panel').upper()
frag={s:pickle.load(open(W+f'/frag_{s}.pkl','rb')) for s in samples}
# build per sample: site -> set of alt fragments (BQ>=20), and depth
info={}
for s in samples:
    dep=collections.Counter(); alt=collections.defaultdict(set)
    for fid,d in frag[s].items():
        for i,calls in d['base'].items():
            p=sorted(candpos)[i] if False else None
    # need mapping i->pos
    sortedpos=sorted(candpos, key=lambda p: candpos[p])
    for fid,d in frag[s].items():
        for i,calls in d['base'].items():
            p=sortedpos[i]
            rb=refseq[p]
            for m,(b,bq,rp) in calls.items():
                if bq<20: continue
                dep[p]+=1
                if b!=rb and b in 'ACGT':
                    pass
    info[s]=(dep,)
# simpler: recompute alt fragment sets per sample
altfrags={}
depths={}
sortedpos=sorted(candpos, key=lambda p: candpos[p])
for s in samples:
    rb_map={p:refseq[p] for p in sortedpos}
    alt=collections.defaultdict(set); dep=collections.Counter()
    for fid,d in frag[s].items():
        for i,calls in d['base'].items():
            p=sortedpos[i]
            good=False
            for m,(b,bq,rp) in calls.items():
                if bq<20: continue
                dep[p]+=1; good=True
                if b!=rb_map[p]:
                    alt[p].add(fid)
                    break
    altfrags[s]=alt; depths[s]=dep
comp={'CG24-4187':'CG24-1366','CG24-7410':'CG24-6425','CG24-9024':'CG24-3973'}
for tum,norm in comp.items():
    others=[s for s in samples if s not in (tum,norm)]
    sites=[]
    for p,fs in altfrags[tum].items():
        if len(fs)<4: continue
        if len(altfrags[norm].get(p,()))>2: continue
        if any(len(altfrags[o].get(p,()))>2 for o in others): continue
        af=len(fs)/max(1,depths[tum][p])
        if af<0.05 or af>0.60: continue
        sites.append((p,fs,af))
    print('==',tum,'private sites 5-60%:',len(sites))
    pairs=collections.Counter()
    for (p1,f1,a1),(p2,f2,a2) in itertools.combinations(sites,2):
        sh=len(f1&f2)
        if sh: pairs[(p1,p2)]=sh
    tot_frag=sum(len(f) for _,f,_ in sites)
    print('   sharing pairs:',len(pairs), 'total alt frags:',tot_frag)
    for k,v in pairs.most_common(10):
        dist=abs(k[0]-k[1])
        print('   ',k,'shared frags',v,'distance',dist)
